This table is computed by the compiler. What does the program print?

```zig
const std = @import("std");

fn sumTo(n: u32) u32 {
    var s: u32 = 0;
    for (1..n + 1) |i| s += @intCast(i);
    return s;
}

const table = blk: {
    var t: [5]u32 = undefined;
    for (&t, 0..) |*x, i| x.* = sumTo(@intCast(i));
    break :blk t;
};

pub fn main() void {
    std.debug.print("{any}\n", .{table});
}
```

